func CountFindingSelect(q *ent.CountFindingQuery, m *rove.CountFindingSelect) {
	if !m.GetAll() {
		fields := CountFindingSelectedFields(m)
		q.Select(fields...)
	}
	if m.HasTenant() {
		q.WithTenant(func(q *ent.TenantQuery) {
			TenantSelect(q, m.GetTenant())
		})
	}
	if m.HasCount() {
		q.WithCount(func(q *ent.InventoryCountQuery) {
			q.Where(inventorycount.DateErasedIsNil())
			InventoryCountSelect(q, m.GetCount())
		})
	}
	if m.HasAsset() {
		q.WithAsset(func(q *ent.AssetQuery) {
			q.Where(asset.DateErasedIsNil())
			AssetSelect(q, m.GetAsset())
		})
	}
}

func CountFindingSelectInit(q *ent.CountFindingQuery, m *rove.CountFindingSelect) {
	if m != nil {
		CountFindingSelect(q, m)
	}
}

